import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));

        in.nextToken();
        int n = (int) in.nval;

        int darioWins = 0;
        for (int i = 0; i < n; i++) {
            in.nextToken();
            int d = (int) in.nval;
            in.nextToken();
            int x = (int) in.nval;

            // Regra derivada do enunciado/exemplos: cada mao vence as duas seguintes no ciclo.
            // Ex.: 1 vence 3 (exemplo 2) e 3 vence 0 (enunciado) -> mao 'a' vence 'b' se (b-a)%5 em {1,2}.
            // Como D != X, (x - d + 5) % 5 esta em {1,2,3,4}; dario vence se for 1 ou 2 (< 3).
            if ((x - d + 5) % 5 < 3) {
                darioWins++;
            }
        }

        // N eh impar, logo nao ha empate: dario vence se ganhou mais da metade das rodadas.
        System.out.println(darioWins * 2 > n ? "dario" : "xerxes");
    }
}
